*{box-sizing:border-box} :root{--ink:#221c38;--muted:#817b94;--paper:#fbf8ff;--lilac:#a998ea;--pink:#ff8fa8;--gold:#ffcf80} html,body{margin:0;min-height:100%;background:#151323;color:#fff;font-family:'DM Sans',sans-serif}body{display:grid;place-items:center;min-height:100svh;padding:16px;background:radial-gradient(ellipse at 50% 0%,#35304d 0,#171523 58%,#11101a 100%)}button{font:inherit;cursor:pointer}.app{position:relative;width:min(1180px,100%);height:min(820px,calc(100svh - 32px));min-height:620px;border:1px solid #ffffff20;border-radius:20px;overflow:hidden;background:#1a1729;box-shadow:0 30px 100px #05040bb0;display:flex;flex-direction:column}.topbar{height:67px;display:flex;align-items:center;justify-content:space-between;padding:0 26px;background:#1b1929;border-bottom:1px solid #ffffff12;z-index:2;flex-shrink:0}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:#b9b1d0;font-size:9px;letter-spacing:1.6px;line-height:1.45}.brand b{color:#fff;font-size:11px}.brand-mark{font-size:23px;color:var(--pink)}.top-actions{display:flex;align-items:center;gap:10px}.chapter-label{font-size:10px;letter-spacing:1.8px;color:#a6a0b7;margin-right:14px}.icon-btn{width:34px;height:34px;border-radius:50%;border:1px solid #ffffff22;background:transparent;color:#e5ddf3;font-size:17px}.icon-btn:hover{background:#ffffff18}.game-shell{display:grid;grid-template-columns:1.08fr .92fr;min-height:0;flex:1;padding:22px;gap:18px}.art-stage{position:relative;overflow:hidden;border-radius:14px;background:#27213d;min-height:0;box-shadow:0 12px 30px #07061055}.art-stage svg,.title-art svg{width:100%;height:100%;display:block;object-fit:cover}.art-overlay{position:absolute;inset:0;background:linear-gradient(180deg,#100d1b40 0%,transparent 42%,#100d1b78 100%);pointer-events:none}.scene-tag{position:absolute;top:17px;left:18px;padding:8px 11px;background:#171426aa;border:1px solid #ffffff25;border-radius:4px;color:#fff;font-size:9px;letter-spacing:2px}.art-caption{position:absolute;bottom:18px;left:19px;color:#fff;font:italic 16px 'Playfair Display',serif;text-shadow:0 2px 6px #000}.story-panel{position:relative;display:flex;flex-direction:column;padding:17px 18px 14px;background:#faf8ff;border-radius:14px;color:var(--ink);box-shadow:0 12px 30px #07061055;min-height:0}.speaker-row{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #e8e2f0;padding-bottom:11px}.speaker{font-size:11px;font-weight:700;letter-spacing:1.8px;color:#7a63ba}.scene-count{font-size:9px;letter-spacing:1.3px;color:#9a93a9}.dialogue{font-size:15px;line-height:1.75;overflow-y:auto;white-space:pre-line;padding:18px 3px 12px;flex:1;scrollbar-color:#d6cce9 transparent}.dialogue strong{color:#6e55b3}.dialogue em{color:#a24d70}.choice-list{display:flex;flex-direction:column;gap:8px;padding:0 0 4px}.choice-btn{border:1px solid #e5deef;border-radius:8px;background:#fff;color:#39334b;text-align:left;padding:11px 13px;font-size:13px;transition:.18s}.choice-btn:hover,.choice-btn:focus{border-color:#a998ea;background:#f4f0ff;transform:translateX(3px);outline:none}.choice-btn span{display:inline-block;color:#a18bd5;font-weight:bold;margin-right:8px}.continue-row{display:flex;align-items:center;justify-content:space-between;padding-top:8px;border-top:1px solid #ece7f2}.hint{font-size:9px;color:#a39bae;letter-spacing:1.1px}.continue-btn{width:35px;height:35px;border:0;border-radius:50%;color:#fff;background:#8068bf;font-size:19px;box-shadow:0 5px 12px #8068bf55;animation:bob 1.6s ease-in-out infinite}.continue-btn:hover{background:#6e55ad}@keyframes bob{50%{transform:translateY(3px)}}.footer{height:34px;display:flex;align-items:center;justify-content:space-between;padding:0 26px;color:#88839a;font-size:8px;letter-spacing:1.4px;flex-shrink:0}.footer i{color:var(--pink);font-style:normal}.title-screen{position:absolute;inset:0;z-index:5;overflow:hidden;background:#27213d}.title-art{position:absolute;inset:0 0 0 34%}.title-art:after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,#181524 0%,#18152420 43%,#18152405 100%),linear-gradient(0deg,#1815249c,transparent 30%)}.title-shade{position:absolute;inset:0;background:linear-gradient(90deg,#171423 0%,#171423f5 30%,#17142390 52%,transparent 82%)}.title-content{position:absolute;left:9%;top:50%;transform:translateY(-50%);width:44%;max-width:480px}.eyebrow{display:flex;align-items:center;gap:10px;color:#c6a9da;font-size:9px;letter-spacing:2.6px;font-weight:700}.eyebrow span{width:24px;height:1px;background:#c6a9da}.title-content h1{font:800 clamp(42px,5.4vw,70px)/.99 'Playfair Display',serif;letter-spacing:-2.3px;margin:17px 0 13px;color:#fff;text-shadow:0 4px 24px #100d18}.title-content h1 em{color:#ff9daf;font-weight:700}.title-sub{font-size:13px;line-height:1.65;color:#cac4d5;max-width:345px;margin:0 0 20px}.title-meta{display:flex;gap:15px;color:#b4a9cf;font-size:8px;letter-spacing:1.1px;margin-bottom:24px}.primary-btn{border:0;border-radius:7px;background:#f48ca5;color:#2a1e35;font-weight:700;font-size:11px;letter-spacing:1.6px;padding:15px 20px;box-shadow:0 7px 22px #f48ca53d;transition:.2s}.primary-btn:hover{background:#ffacc0;transform:translateY(-2px)}.primary-btn span{margin-left:22px;font-size:16px}.text-btn{display:block;color:#c9bfd7;background:transparent;border:0;font-size:10px;letter-spacing:1.5px;padding:14px 0 0}.text-btn:hover{color:#fff}.safety-note{font-size:9px;color:#958ca8;margin-top:22px}.title-credit{position:absolute;bottom:18px;right:21px;font-size:8px;letter-spacing:1.5px;color:#d0c9d8a6}.modal-backdrop{position:absolute;inset:0;z-index:10;background:#100e18bb;display:grid;place-items:center;padding:20px}.modal-backdrop[hidden]{display:none}.modal{position:relative;width:min(390px,100%);padding:33px;border-radius:14px;background:#fbf8ff;color:var(--ink);box-shadow:0 20px 70px #0009}.modal h2{font:700 29px 'Playfair Display',serif;margin:13px 0}.modal p{color:#716a80;line-height:1.6;font-size:13px}.modal-close{position:absolute;right:15px;top:13px;border:0;background:none;color:#79718d;font-size:25px}.modal-actions{margin-top:22px}.modal-actions .primary-btn{width:100%}.modal-actions .text-btn{color:#817990}.toast{position:absolute;z-index:11;bottom:48px;left:50%;transform:translate(-50%,15px);background:#29243c;color:#fff;padding:11px 16px;border:1px solid #ffffff22;border-radius:30px;font-size:12px;opacity:0;transition:.25s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.ending-card{text-align:center}.ending-stamp{color:#a084cb;font-size:10px;letter-spacing:2px;font-weight:700;margin-bottom:9px}.end-actions{display:flex;gap:8px}.end-actions .choice-btn{flex:1;text-align:center}.hide{display:none!important}
@media(max-width:780px){body{padding:0;display:block}.app{width:100%;height:100svh;min-height:560px;border:0;border-radius:0}.topbar{height:55px;padding:0 15px}.game-shell{display:flex;flex-direction:column;padding:11px;gap:10px}.art-stage{flex:1;min-height:190px}.story-panel{flex:1.04;padding:13px 14px 10px}.dialogue{font-size:14px;padding:12px 2px 8px;line-height:1.65}.choice-btn{padding:10px;font-size:12px}.footer{height:27px;padding:0 14px;font-size:7px}.chapter-label{font-size:8px;margin-right:5px}.title-art{inset:0}.title-art:after{background:linear-gradient(90deg,#171423ee 0%,#171423aa 50%,#17142320),linear-gradient(0deg,#171423dd,transparent 47%)}.title-shade{background:linear-gradient(0deg,#171423c9,transparent 80%)}.title-content{left:8%;top:46%;width:84%}.title-content h1{font-size:clamp(46px,13vw,68px)}.title-sub{font-size:12px;max-width:300px}.title-meta{gap:9px;font-size:7px}.title-credit{font-size:7px;right:12px;bottom:10px}.safety-note{margin-top:16px}.scene-tag{top:12px;left:12px;font-size:8px}.art-caption{bottom:11px;left:12px;font-size:14px}}
@media(max-height:700px) and (min-width:781px){.app{min-height:0;height:calc(100svh - 16px)}.game-shell{padding:15px}.dialogue{font-size:14px;padding-top:12px}.title-content h1{font-size:55px}}

  const scenesEnd = [];
  // Original SVG anime-inspired illustrations are generated locally from scene and character data.
  const esc = (s) => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function person(x,y,scale,who,pose='stand') {
    const c=cast[who], bodyY=pose==='sit'?60:60, arm=pose==='wave'?`<path d="M-24 71 Q-54 49 -52 28 Q-50 13 -40 17" fill="none" stroke="${c.outfit}" stroke-width="13" stroke-linecap="round"/><path d="M-40 20 Q-39 6 -29 9" fill="none" stroke="#f1c5b7" stroke-width="8" stroke-linecap="round"/>`:`<path d="M-24 72 Q-49 90 -44 112" fill="none" stroke="${c.outfit}" stroke-width="13" stroke-linecap="round"/><path d="M24 72 Q44 90 40 112" fill="none" stroke="${c.outfit}" stroke-width="13" stroke-linecap="round"/>`;
    return `<g transform="translate(${x} ${y}) scale(${scale})"><ellipse cx="0" cy="113" rx="33" ry="8" fill="#211c3a" opacity=".23"/><path d="M-21 100 L-22 135 M19 100 L22 135" stroke="#f0c3b4" stroke-width="10" stroke-linecap="round"/><path d="M-22 134 L-35 137 M22 134 L35 137" stroke="#473a57" stroke-width="9" stroke-linecap="round"/><path d="M-32 48 Q0 32 32 48 L28 102 Q0 116 -28 102Z" fill="${c.outfit}" stroke="#ffffffaa" stroke-width="2"/>${arm}<path d="M-25 43 Q-34 11 -23 -10 Q-20 -37 2 -38 Q31 -37 33 -3 L27 43 Q11 31 -25 43" fill="${c.hair}"/><ellipse cx="0" cy="5" rx="25" ry="30" fill="#f5d1c5"/><path d="M-25 3 Q-30 -30 -5 -37 Q21 -43 30 -10 Q15 -21 7 -24 Q-3 -8 -24 -8Z" fill="${c.hair}"/><path d="M-15 -1 Q-5 -7 0 -2 M8 -2 Q16 -7 21 -1" stroke="#443450" stroke-width="2" fill="none" stroke-linecap="round"/><ellipse cx="-9" cy="7" rx="4.3" ry="6" fill="${c.eyes}"/><ellipse cx="12" cy="7" rx="4.3" ry="6" fill="${c.eyes}"/><circle cx="-8" cy="5" r="1.5" fill="white"/><circle cx="13" cy="5" r="1.5" fill="white"/><path d="M-4 18 Q2 22 8 17" fill="none" stroke="#b36e70" stroke-width="1.8" stroke-linecap="round"/><circle cx="-18" cy="14" r="4" fill="#ee9a9c" opacity=".4"/><circle cx="19" cy="14" r="4" fill="#ee9a9c" opacity=".4"/><path d="M0 37 L0 48" stroke="${c.accent}" stroke-width="3"/><path d="M-17 55 Q0 65 17 55" stroke="${c.accent}" stroke-width="2" fill="none"/><path d="M-28 92 Q0 105 27 92" stroke="#ffffffaa" stroke-width="2" fill="none"/><path d="M-21 101 L-23 134 M20 101 L23 134" stroke="#303045" stroke-width="2" opacity=".5"/></g>`;
  }
  function sceneSvg(type) {
    const base=(sky,ground,content,extra='')=>`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 760 850" preserveAspectRatio="xMidYMid slice" role="img" aria-label="Original anime-inspired illustrated visual novel scene"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="${sky}"/><stop offset="1" stop-color="#f5bac4"/></linearGradient><linearGradient id="ground" x2="0" y2="1"><stop stop-color="${ground}"/><stop offset="1" stop-color="#353252"/></linearGradient><radialGradient id="glow"><stop stop-color="#fff5d5" stop-opacity=".8"/><stop offset="1" stop-color="#fff5d5" stop-opacity="0"/></radialGradient></defs><rect width="760" height="850" fill="url(#sky)"/>${extra}<circle cx="575" cy="175" r="150" fill="url(#glow)"/><rect y="570" width="760" height="280" fill="url(#ground)"/>${content}<path d="M0 655 Q200 635 370 657 T760 646" fill="none" stroke="#ffffff45" stroke-width="4"/><rect width="760" height="850" fill="none" stroke="#fff" stroke-opacity=".12" stroke-width="12"/></svg>`;
    if(type==='home'||type==='door') return base('#a78fc3','#4c4768',`<path d="M65 394 L370 170 L695 394 V670 H65Z" fill="#fff0dd"/><path d="M30 402 L369 142 L726 402" fill="none" stroke="#514261" stroke-width="29"/><path d="M105 417 H653 V660 H105Z" fill="#f5d9c9"/><rect x="360" y="415" width="160" height="245" rx="2" fill="#826a78"/><rect x="532" y="448" width="98" height="101" fill="#8eb1bb"/><path d="M581 448V549 M532 499H630" stroke="#fff5df" stroke-width="9"/><circle cx="497" cy="535" r="6" fill="#ffcf80"/><path d="M65 646 H692" stroke="#f9d5a5" stroke-width="14"/><path d="M0 580 Q120 510 200 590 M650 570 Q700 493 760 570" fill="none" stroke="#4d735a" stroke-width="35"/>${person(260,487,.97,'ren')}${person(565,488,.98,'kimi','wave')}${type==='door'?`<g transform="translate(155 565)"><rect width="70" height="58" rx="5" fill="#bd8c70"/><path d="M8 16H62M35 2V55" stroke="#e9c2a2" stroke-width="3"/></g>`:''}`);
    if(type==='beach') return base('#75bed3','#287d9c',`<path d="M0 496 Q120 462 240 500 T480 495 T760 486 V690 H0Z" fill="#48a9b5"/><path d="M0 568 Q130 541 250 570 T500 569 T760 560" fill="none" stroke="#d5f1e7" stroke-width="15"/><path d="M0 635 Q150 605 320 635 T760 625" fill="none" stroke="#a8dcca" stroke-width="8"/><path d="M0 670 Q230 627 420 689 T760 667 V850 H0Z" fill="#efcf9d"/><path d="M70 378 Q102 282 135 378Z" fill="#385b62"/><path d="M105 375V581" stroke="#855b4f" stroke-width="12"/><path d="M98 392 Q205 394 285 430 L103 434Z" fill="#ff9ea9"/><circle cx="643" cy="214" r="57" fill="#fff1bb"/>${person(295,468,.94,'ren')}${person(427,464,.94,'emi','wave')}${person(558,489,.83,'kimi')}`,'<path d="M0 530 Q120 500 260 535T520 530T760 515" fill="none" stroke="#fff" stroke-opacity=".35" stroke-width="3"/>');
    if(type==='sunset') return base('#ec9f99','#e7aa85',`<circle cx="390" cy="360" r="160" fill="#ffe6aa"/><path d="M0 505 Q210 465 380 500 T760 487 V680 H0Z" fill="#7e7190"/><path d="M0 592 Q170 554 340 592 T760 575" fill="none" stroke="#ffdab0" stroke-width="10"/><path d="M0 660 Q230 618 450 661 T760 644 V850 H0Z" fill="#413952"/><path d="M50 670 Q240 632 480 681" fill="none" stroke="#ffffff30" stroke-width="5"/>${person(330,485,.95,'ren')}${person(428,485,.95,'emi')}`);
    if(type==='inn') return base('#6c7798','#506354',`<path d="M0 476 Q90 286 190 475 M80 485 Q200 227 332 480 M455 471 Q560 205 760 466" fill="#65745d"/><path d="M136 430 L377 255 L629 430 V625 H136Z" fill="#f5e7d4"/><path d="M100 438 L378 225 L666 438" fill="none" stroke="#4b3b4e" stroke-width="27"/><rect x="210" y="455" width="110" height="166" fill="#705b61"/><rect x="430" y="472" width="122" height="98" fill="#a9ccd0"/><path d="M490 472V570 M430 521H552" stroke="#fff2d6" stroke-width="8"/><path d="M0 655 Q160 617 310 654 T760 640" fill="none" stroke="#d0e4dd" stroke-width="7"/><path d="M30 696 Q205 673 372 700 T760 689" fill="none" stroke="#a9d8d1" stroke-width="4"/>${person(280,483,.89,'ren')}${person(470,481,.89,'emi')}${person(578,497,.74,'kimi')}`,'<circle cx="150" cy="150" r="80" fill="#fff" opacity=".13"/>');
    if(type==='festival'||type==='ending') return base('#584f82','#34324d',`<circle cx="580" cy="185" r="112" fill="#ffb49e" opacity=".72"/><path d="M0 562 Q160 512 335 564 T760 542 V850 H0Z" fill="#34334d"/><path d="M0 674 Q240 620 440 672 T760 652" fill="none" stroke="#8993bd" stroke-width="6"/><path d="M70 204V623 M690 204V620" stroke="#45374f" stroke-width="9"/><path d="M70 248 Q375 298 690 248" fill="none" stroke="#ffd5ab" stroke-width="6"/><g fill="#ffcc92"><path d="M170 264 Q145 305 170 338 Q195 305 170 264Z"/><path d="M315 279 Q290 320 315 352 Q340 320 315 279Z"/><path d="M462 281 Q437 323 462 355 Q487 323 462 281Z"/><path d="M590 258 Q565 298 590 332 Q615 298 590 258Z"/></g><g fill="#ffb887" opacity=".9"><circle cx="180" cy="138" r="16"/><circle cx="233" cy="200" r="10"/><circle cx="433" cy="155" r="13"/><circle cx="523" cy="112" r="9"/><circle cx="663" cy="363" r="12"/><circle cx="104" cy="359" r="10"/></g>${person(292,484,.92,'ren')}${person(418,481,.92,'emi')}${person(540,493,.81,'kimi')}`,'<path d="M0 0H760V850H0Z" fill="#231e3870"/>');
    if(type==='road'||type==='tragedy') return base(type==='tragedy'?'#27223b':'#9a7f9c','#4d465b',`<path d="M0 519 Q200 481 390 527 T760 500 V850 H0Z" fill="#343447"/><path d="M0 693 H760" stroke="#f4d5a3" stroke-width="7" stroke-dasharray="42 28"/><path d="M95 565 L225 565 L248 634 L70 634Z" fill="#dfac82"/><path d="M111 586H210 M130 607H220" stroke="#f5d8ad" stroke-width="7"/><g transform="translate(562 480)"><rect width="105" height="125" rx="8" fill="#b88b73"/><path d="M15 20H90M15 45H90" stroke="#f1d4b1" stroke-width="6"/><circle cx="25" cy="123" r="11" fill="#25243a"/><circle cx="80" cy="123" r="11" fill="#25243a"/></g>${type==='road'?person(340,484,.94,'ren'):''}${person(433,493,.85,'kimi')}${type==='road'?person(230,488,.9,'emi'):''}<path d="M0 0H760V850H0Z" fill="${type==='tragedy'?'#100e20a8':'#fff0d012'}"/>`);
    return sceneSvg('home');
  }

  function updateArt(scene) { ui.stage.querySelector('svg')?.remove(); ui.stage.insertAdjacentHTML('afterbegin',sceneSvg(scene.art)); ui.tag.textContent=scene.tag; ui.caption.textContent=scene.caption; }
  function save() { try { localStorage.setItem(SAVE_KEY,JSON.stringify(state)); } catch(_){} }
  function load() { try { const s=JSON.parse(localStorage.getItem(SAVE_KEY)||'null'); if(s&&Number.isInteger(s.index)&&s.index<scenes.length){Object.assign(state,s);return true;} } catch(_){} return false; }
  function updateScene() {
    const s=scenes[state.index]; if(!s)return;
    state.ending=s.ending||null;
    ui.chapter.textContent=s.chapter; ui.count.textContent=`${s.chapter} · ${state.index+1} / ${scenes.length}`;
    ui.speaker.textContent=s.speaker; ui.dialogue.innerHTML=s.text;
    ui.choices.innerHTML=''; ui.continueRow.classList.remove('hide');
    if(s.choices){ui.continueRow.classList.add('hide');s.choices.forEach(([label,target,effect],i)=>{const b=document.createElement('button');b.className='choice-btn';b.innerHTML=`<span>${String.fromCharCode(65+i)}.</span>${esc(label)}`;b.addEventListener('click',()=>choose(target,effect));ui.choices.appendChild(b);});}
    if(s.next!==undefined){ui.continueRow.classList.remove('hide');$('continue-btn').onclick=()=>go(s.next);}
    else if(s.ending){ui.continueRow.classList.add('hide');const box=document.createElement('div');box.className='end-actions';box.innerHTML='<button class="choice-btn" data-again>↻ &nbsp; PLAY AGAIN</button><button class="choice-btn" data-menu>☰ &nbsp; MENU</button>';ui.choices.appendChild(box);box.querySelector('[data-again]').onclick=()=>start();box.querySelector('[data-menu]').onclick=()=>openMenu();}
    updateArt(s); save();
  }
  function choose(target,effect={}) { Object.entries(effect).forEach(([k,v])=>{if(typeof state[k]==='number')state[k]+=v;}); if(target==='tragedy'){state.index=19;} else go(target); }
  function go(index) { state.index=index; if(index===6)state.seenBeach=true; if(index===9)state.seenBath=true; updateScene(); }
  function start() { Object.assign(state,{index:0,kimi:0,emi:0,seenBeach:false,seenBath:false,ending:null}); ui.title.classList.add('hide'); updateScene(); }
  function openMenu(){ $('modal-title').textContent='Story menu';$('modal-copy').textContent='Your story is saved automatically. Your choices shape the final chapter.';ui.modal.hidden=false; }
  function toast(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');setTimeout(()=>ui.toast.classList.remove('show'),1900);}
  ui.titleArt.innerHTML=sceneSvg('festival');
  $('start-btn').addEventListener('click',start);
  $('continue-save-btn').addEventListener('click',()=>{if(load()){ui.title.classList.add('hide');updateScene();toast('Welcome back!');}else toast('No saved story yet — start a new one!');});
  $('menu-btn').addEventListener('click',openMenu);
  $('sound-btn').addEventListener('click',()=>toast('Sound effects are off — enjoy the soundtrack in your imagination.'));
  $('modal-close').addEventListener('click',()=>ui.modal.hidden=true);
  $('resume-btn').addEventListener('click',()=>ui.modal.hidden=true);
  $('restart-btn').addEventListener('click',()=>{ui.modal.hidden=true;start();});
  ui.modal.addEventListener('click',e=>{if(e.target===ui.modal)ui.modal.hidden=true;});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!ui.modal.hidden)ui.modal.hidden=true;else if(e.key===' '&&!ui.title.classList.contains('hide')===false&&ui.modal.hidden){const s=scenes[state.index];if(s&&s.next!==undefined)go(s.next);}});
  // Start screen is the default; saved games can be resumed from its title menu.
})();

